"use client"

import { useState, useEffect } from "react"
import TabNavigation from "../components/TabNavigation"
import WRFSection from "../components/WRFSection"
import GasesSection from "../components/GasesSection"
import FWISection from "../components/FWISection"
import VientosSection from "../components/VientosSection"
import { fetchProductos, fetchEstadisticas } from "../services/api"

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState("WRF")
  const [productos, setProductos] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [estadisticas, setEstadisticas] = useState(null)

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    try {
      setLoading(true)
      setError(null)
      const [productosData, statsData] = await Promise.all([
        fetchProductos().catch(err => {
          console.warn("Error fetching productos:", err)
          return { results: [] }
        }), 
        fetchEstadisticas().catch(err => {
          console.warn("Error fetching estadisticas:", err)
          return null
        })
      ])
      setProductos(productosData.results || productosData || [])
      setEstadisticas(statsData)
    } catch (error) {
      console.error("Error loading data:", error)
      setError("Error al cargar los datos")
      setProductos([])
      setEstadisticas(null)
    } finally {
      setLoading(false)
    }
  }

  const renderActiveSection = () => {
    const commonProps = { productos, loading, onRefresh: loadData }

    switch (activeTab) {
      case "WRF":
        return <WRFSection {...commonProps} />
      case "FWI":
        return <FWISection {...commonProps} />
      case "Gases":
        return <GasesSection {...commonProps} />
      case "Vientos":
        return <VientosSection {...commonProps} />
      default:
        return <WRFSection {...commonProps} />
    }
  }

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="card">
          <div className="flex flex-wrap gap-3 justify-center">
            <div className="tab-button-inactive flex items-center space-x-3 min-w-[140px] animate-pulse">
              <div className="h-5 w-5 bg-gray-300 rounded"></div>
              <div className="text-left">
                <div className="font-semibold bg-gray-300 h-4 w-16 rounded"></div>
                <div className="text-xs bg-gray-200 h-3 w-20 rounded mt-1"></div>
              </div>
            </div>
          </div>
        </div>
        <div className="card">
          <div className="text-center py-8">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Cargando datos meteorológicos...</p>
          </div>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="space-y-6">
        <div className="card">
          <div className="text-center py-8">
            <div className="text-red-600 mb-4">
              <svg className="h-12 w-12 mx-auto" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
              </svg>
            </div>
            <h3 className="text-lg font-semibold text-gray-800 mb-2">Error al cargar datos</h3>
            <p className="text-gray-600 mb-4">{error}</p>
            <button 
              onClick={loadData}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              Reintentar
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <TabNavigation activeTab={activeTab} onTabChange={setActiveTab} estadisticas={estadisticas} />
      <div className="animate-slide-up">{renderActiveSection()}</div>
    </div>
  )
}

export default Dashboard
